// Synthetic native UI qualification only: no model, push or audio provider.
import express from 'express';
import http from 'node:http';
import {WebSocketServer} from 'ws';
const app=express();app.use(express.json());const server=http.createServer(app),ws=new WebSocketServer({server});
const requests=[];let failRead=false;let outgoing=[];let notes=[{id:'source-answer',text:'Use 3840 × 2160 pixels for the final image.',question:'What size should the final image be?',manual:0,at:Date.now()}];const thread={id:'alpha23-task',name:'Synthetic recovery study',cwd:'/synthetic',status:{type:'idle'},updatedAt:Date.now()/1000,preview:'A meaningful answer beside a failed delivery.',watched:true};
const timeline={rows:[{id:'source-question',turnId:'synthetic',kind:'user',role:'user',text:'What size should the final image be?'},{id:'synthetic/source-answer',itemId:'source-answer',turnId:'synthetic',phase:'final_answer',kind:'message',role:'assistant',text:'Use 3840 × 2160 pixels for the final image.'},{id:'source-progress',turnId:'synthetic',kind:'message',phase:'commentary',role:'assistant',text:'The lighting pass is ready for review.'}],hasEarlier:false};
function emit(state='queued',id='fixture-update'){for(const s of ws.clients)s.send(JSON.stringify({type:'reply',threadId:thread.id,id,state}));}
app.get('/fixture/state',(_,r)=>r.json({requests,outgoing}));
app.post('/fixture/set',(q,r)=>{requests.length=0;if(Array.isArray(q.body.outgoing))outgoing=q.body.outgoing;if(typeof q.body.failRead==='boolean')failRead=q.body.failRead;if(q.body.notes)notes=q.body.notes;if(typeof q.body.answerText==='string')timeline.rows[1].text=q.body.answerText;emit();r.json({ok:true});});
app.get('/health',(_,r)=>r.json({ok:true,codex:true}));app.get('/api/status',(_,r)=>r.json({connected:true,deviceId:'alpha23-fixture',host:'Synthetic alpha23',local:true,usage:{state:'available',updatedAt:Date.now(),weekly:{remainingPercent:68,resetsAt:Math.floor(Date.now()/1000)+172800}}}));
app.get('/api/threads',(_,r)=>r.json({threads:[thread]}));
app.get('/api/threads/:id',(_,r)=>failRead?r.status(503).json({error:'Synthetic Codex history unavailable after acknowledged action'}):r.json({thread:{...thread,turns:[]},timeline,revision:1,notes,pending:[],notifications:[],outgoing,watched:true}));
app.post('/api/threads/:thread/replies/:id',(q,r)=>{const row=outgoing.find(x=>x.id===q.params.id);requests.push({id:q.params.id,body:q.body,authenticated:q.headers.authorization==='Bearer synthetic-alpha23-only'});if(row?.state==='unknown'&&q.body.action==='retry'&&q.body.confirmUnknown!==true)return r.status(409).json({error:'Explicit confirmation required'});if(row?.state==='accepted')return r.status(409).json({error:'Already accepted'});if(q.body.action==='remove'){if(row)row.state='cancelled';outgoing=outgoing.filter(x=>x.id!==q.params.id);}else if(q.body.action==='retry'&&row)row.state='accepted';else if(q.body.action==='edit'&&row)row.text=q.body.text;emit(q.body.action==='remove'?'cancelled':row?.state,q.params.id);r.json({id:q.params.id,state:q.body.action==='retry'?'queued':row?.state});});
app.post('/api/threads/:id/notes/remove',(q,r)=>{requests.push({noteRemove:q.body.id});notes=notes.filter(n=>n.id!==q.body.id);r.json({notes});});
app.post('/api/threads/:id/reply',(q,r)=>{requests.push({newReply:q.body});r.json({state:'accepted'});});
for(const p of ['notifications','attention'])app.get('/api/'+p,(_,r)=>r.json({notifications:[]}));app.get('/api/activity',(_,r)=>r.json({items:[]}));app.get('/api/projects',(_,r)=>r.json({projects:[]}));app.get('/api/immersion',(_,r)=>r.json({enabled:false,translations:[]}));app.get('/api/app/update',(_,r)=>r.json({available:false}));app.use((_,r)=>r.json({ok:true}));ws.on('connection',s=>s.send(JSON.stringify({type:'status',connected:true})));server.listen(19988,'127.0.0.1',()=>console.log('Synthetic alpha23 fixture19988'));
